-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS gamification_badges_update_audit ON engagement.gamification_badges;
CREATE TRIGGER gamification_badges_update_audit BEFORE UPDATE ON engagement.gamification_badges
